def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Find the 3x3 motifs: a 2 at the center surrounded by 3s.
    motifs = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(
                g[rr][cc] == (2 if (rr, cc) == (r, c) else 3)
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
            ):
                motifs.append((r, c))

    # Long lines of 2s act as rails.
    vertical_rails = [
        c for c in range(w)
        if sum(grid[r][c] == 2 for r in range(h)) >= h // 2
    ]
    horizontal_rails = [
        r for r in range(h)
        if sum(grid[r][c] == 2 for c in range(w)) >= w // 2
    ]

    def set_one(r, c, overwrite=False):
        if 0 <= r < h and 0 <= c < w:
            if g[r][c] == 0 or (overwrite and g[r][c] == 2):
                g[r][c] = 1

    if len(vertical_rails) >= len(horizontal_rails):
        # Draw horizontal strokes through each motif.
        for r, c in motifs:
            for x in range(w):
                set_one(r, x)
            # Mark each rail crossing with a 3x3 patch, keeping its center 2.
            for x in vertical_rails:
                if x == c:
                    continue
                for rr in range(r - 1, r + 2):
                    for cc in range(x - 1, x + 2):
                        if (rr, cc) != (r, x):
                            set_one(rr, cc, overwrite=True)
    else:
        # Draw vertical strokes through each motif.
        for r, c in motifs:
            for x in range(h):
                set_one(x, c)
            for x in horizontal_rails:
                if x == r:
                    continue
                for rr in range(x - 1, x + 2):
                    for cc in range(c - 1, c + 2):
                        if (rr, cc) != (x, c):
                            set_one(rr, cc, overwrite=True)

    return g
